{"command":"create","path":"/root/output/css/style.css","security_risk":"MEDIUM","summary":"Create stock visualization styling","file_text":":root {
  --ink: #14202b;
  --muted: #6e7c86;
  --soft: #9ba7ae;
  --line: #dfe6e8;
  --paper: #f5f7f5;
  --panel: #ffffff;
  --deep: #142b36;
  --lime: #c8ef7c;
  --shadow: 0 18px 55px rgba(22, 45, 55, 0.08);
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  color: var(--ink);
  background: var(--paper);
}

* { box-sizing: border-box; }

html { min-width: 1180px; background: var(--paper); }

body {
  min-width: 1180px;
  margin: 0;
  background:
    radial-gradient(circle at 12% 4%, rgba(200, 239, 124, 0.22), transparent 24rem),
    linear-gradient(135deg, #f7f9f7 0%, #eef3f1 100%);
}

button, table { font: inherit; }

.app-shell { width: min(1600px, calc(100% - 64px)); margin: 0 auto; padding: 50px 0 28px; }

.page-header { margin-bottom: 26px; }

.kicker, .panel-label, .panel-meta, .stat-label, .chart-footer, .page-footer {
  text-transform: uppercase;
  letter-spacing: 0.12em;
  font-size: 10px;
  font-weight: 700;
}

.kicker { display: flex; align-items: center; gap: 9px; color: var(--muted); }
.kicker-dot { display: inline-block; width: 8px; height: 8px; border-radius: 50%; background: var(--lime); box-shadow: 0 0 0 4px rgba(200, 239, 124, .24); }
.kicker-divider { color: #bbc6c7; }

.header-row { display: flex; justify-content: space-between; align-items: end; gap: 32px; }
h1 { max-width: 700px; margin: 13px 0 8px; color: var(--deep); font: 600 clamp(42px, 5vw, 72px)/0.98 Georgia, "Times New Roman", serif; letter-spacing: -0.05em; }
.intro { max-width: 660px; margin: 0; color: var(--muted); font-size: 15px; line-height: 1.55; }
.header-mark { position: relative; width: 150px; height: 102px; flex: 0 0 150px; }
.mark-ring { position: absolute; display: block; border: 1px solid rgba(20, 43, 54, .18); border-radius: 50%; }
.mark-ring-one { width: 76px; height: 76px; right: 5px; top: 3px; background: rgba(200, 239, 124, .55); border-color: transparent; }
.mark-ring-two { width: 54px; height: 54px; right: 62px; top: 38px; background: #e4edf0; }
.mark-ring-three { width: 23px; height: 23px; right: 31px; top: 68px; background: #f5c4ad; border-color: transparent; }

.stat-strip { display: flex; gap: 38px; margin-top: 30px; padding-top: 17px; border-top: 1px solid var(--line); }
.stat { display: flex; align-items: baseline; gap: 7px; }
.stat-value { color: var(--deep); font-size: 17px; font-weight: 750; letter-spacing: -0.03em; }
.stat-label { color: var(--soft); font-size: 9px; }

.workspace { display: grid; grid-template-columns: minmax(0, 1.23fr) minmax(550px, .77fr); gap: 18px; align-items: stretch; }
.panel { min-width: 0; background: var(--panel); border: 1px solid rgba(211, 222, 223, .9); border-radius: 8px; box-shadow: var(--shadow); }
.chart-panel { padding: 24px 24px 18px; }
.table-panel { display: flex; min-height: 752px; flex-direction: column; padding: 24px 0 0; overflow: hidden; }
.panel-heading { display: flex; align-items: start; justify-content: space-between; gap: 12px; }
.panel-label { color: #92a0a3; font-size: 9px; }
h2 { margin: 6px 0 0; color: var(--deep); font-size: 22px; line-height: 1.1; letter-spacing: -0.035em; }
.panel-meta { margin-top: 2px; color: #9aa9a9; font-size: 9px; white-space: nowrap; }
.table-heading { padding: 0 24px; }
.table-intro { margin: 20px 24px 16px; color: var(--muted); font-size: 12px; line-height: 1.45; }

.legend { display: flex; flex-wrap: wrap; gap: 8px 15px; min-height: 24px; margin: 23px 0 4px; }
.legend-item { display: inline-flex; align-items: center; gap: 6px; color: #6e7b80; font-size: 10px; font-weight: 650; }
.legend-swatch { width: 9px; height: 9px; border-radius: 50%; box-shadow: inset 0 0 0 1px rgba(20, 43, 54, .08); }

.chart-frame { position: relative; width: 100%; margin-top: 4px; overflow: hidden; border-radius: 5px; background: radial-gradient(circle at 50% 50%, #fbfdfb 0%, #f6f9f7 72%, #f1f5f3 100%); }
#stock-bubbles { display: block; width: 100%; height: auto; min-height: 560px; }
.cluster-label { fill: #a8b5b3; font-size: 9px; font-weight: 750; letter-spacing: .12em; text-anchor: middle; text-transform: uppercase; }
.cluster-halo { fill: none; stroke: rgba(154, 173, 166, .19); stroke-dasharray: 2 7; }
.bubble { cursor: pointer; outline: none; }
.bubble circle { stroke: rgba(255, 255, 255, .95); stroke-width: 2; transition: filter .16s ease, stroke-width .16s ease; }
.bubble.etf circle { stroke-dasharray: 3 2; }
.bubble:hover circle, .bubble:focus circle { filter: brightness(.96) saturate(1.06); stroke: var(--deep); stroke-width: 3; }
.bubble.selected circle { stroke: var(--deep); stroke-width: 4; filter: drop-shadow(0 4px 5px rgba(20, 43, 54, .18)); }
.bubble-label { fill: #173440; font-weight: 800; letter-spacing: .035em; text-anchor: middle; dominant-baseline: central; pointer-events: none; user-select: none; }
.bubble.etf .bubble-label { fill: #34535a; }

.chart-footer { display: flex; flex-wrap: wrap; gap: 15px 25px; padding-top: 10px; color: #8c999c; font-size: 9px; letter-spacing: .05em; }
.footer-key { display: inline-block; width: 7px; height: 7px; margin-right: 6px; border-radius: 50%; background: var(--deep); }
.footer-key-etf { background: transparent; border: 1px dashed #859b9c; }

.table-wrap { flex: 1; overflow: auto; border-top: 1px solid var(--line); }
table { width: 100%; border-collapse: collapse; table-layout: fixed; }
thead { position: sticky; top: 0; z-index: 2; background: #f8faf9; }
th { padding: 12px 8px; color: #93a0a1; border-bottom: 1px solid var(--line); text-align: left; text-transform: uppercase; letter-spacing: .1em; font-size: 9px; font-weight: 750; }
th:first-child, td:first-child { padding-left: 24px; }
th:last-child, td:last-child { padding-right: 24px; }
th:nth-child(1) { width: 19%; }
th:nth-child(2) { width: 39%; }
th:nth-child(3) { width: 22%; }
th:nth-child(4) { width: 20%; }
.numeric, td.numeric { text-align: right; }
tbody tr { cursor: pointer; border-bottom: 1px solid #edf1ef; transition: background .13s ease, box-shadow .13s ease; }
tbody tr:hover { background: #f5f9f4; }
tbody tr.selected { background: #eaf5dd; box-shadow: inset 4px 0 0 var(--lime); }
tbody tr:focus { outline: 2px solid #9dcc61; outline-offset: -2px; }
td { padding: 10px 8px; color: #52636a; font-size: 11px; line-height: 1.2; vertical-align: middle; }
td.ticker-cell { color: var(--deep); font-size: 11px; font-weight: 800; letter-spacing: .04em; }
td.name-cell { overflow: hidden; color: #4f6066; text-overflow: ellipsis; white-space: nowrap; }
td.sector-cell { color: #78888b; }
td.cap-cell { color: var(--deep); font-variant-numeric: tabular-nums; font-weight: 700; }
td.cap-cell.etf-cap { color: #9aa6a5; font-weight: 550; }

.tooltip { position: fixed; z-index: 10; max-width: 270px; padding: 12px 14px; pointer-events: none; color: #eaf3ee; background: rgba(20, 43, 54, .96); border: 1px solid rgba(214, 239, 196, .28); border-radius: 5px; box-shadow: 0 10px 28px rgba(20, 43, 54, .2); opacity: 0; transform: translateY(5px); transition: opacity .12s ease, transform .12s ease; }
.tooltip.visible { opacity: 1; transform: translateY(0); }
.tooltip-ticker { display: block; margin-bottom: 4px; color: var(--lime); font-size: 12px; font-weight: 800; letter-spacing: .08em; }
.tooltip-name { display: block; margin-bottom: 5px; font-size: 12px; line-height: 1.35; }
.tooltip-sector { display: block; color: #b7c9c4; font-size: 10px; letter-spacing: .06em; text-transform: uppercase; }

.page-footer { display: flex; justify-content: space-between; gap: 20px; padding: 18px 1px 0; color: #8d9a9b; font-size: 9px; letter-spacing: .06em; }
.footer-note { color: #aab6b4; }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0; }

@media (max-width: 1320px) {
  .workspace { grid-template-columns: minmax(0, 1.08fr) minmax(525px, .92fr); }
  .app-shell { width: min(1500px, calc(100% - 40px)); }
}
"}

