{"command":"create","path":"/root/output/js/visualization.js","security_risk":"MEDIUM","summary":"Create D3 force-clustered stock visualization logic","file_text":"/*
 * Offline stock market map.
 * The canonical records below were parsed from ../data/stock-descriptions.csv.
 * All rendering uses this single normalized array so bubbles and rows cannot drift.
 */
(function () {
  "use strict";

  const SOURCE_RECORDS = __CANONICAL_RECORDS__;
  const WIDTH = 860;
  const HEIGHT = 660;
  const SECTOR_ORDER = ["Information Technology", "Industry", "Energy", "Financial", "ETF"];
  const SECTOR_COLORS = {
    "Information Technology": "#8bbf91",
    "Industry": "#e5ae80",
    "Energy": "#d78578",
    "Financial": "#7fa9c5",
    "ETF": "#b2a1d2"
  };
  const CLUSTER_ANCHORS = {
    "Information Technology": { x: 210, y: 178 },
    "Industry": { x: 650, y: 178 },
    "Energy": { x: 210, y: 468 },
    "Financial": { x: 650, y: 468 },
    "ETF": { x: 430, y: 325 }
  };

  function normalizeTicker(value) {
    return String(value || "").trim().toUpperCase();
  }

  function finitePositive(value) {
    const number = Number(value);
    return Number.isFinite(number) && number > 0 ? number : null;
  }

  function historyFilename(ticker) {
    const normalized = normalizeTicker(ticker);
    return normalized === "GLD" || normalized === "QQQ" || normalized === "SPY" ||
      normalized === "VEA" || normalized === "VOO" || normalized === "VTV" ||
      normalized === "VWO" || normalized === "XLF" || normalized === "XLU" ||
      normalized === "XLV" ? normalized.toLowerCase() + ".csv" : normalized + ".csv";
  }

  // Keep the source order stable: it groups the supplied records by sector.
  const stocks = SOURCE_RECORDS.map(function (record, index) {
    const ticker = normalizeTicker(record.ticker);
    const sector = String(record.sector || "").trim();
    const marketCap = finitePositive(record.marketCap);
    const isETF = sector === "ETF";
    return {
      sourceIndex: index,
      ticker: ticker,
      tickerKey: ticker,
      sector: sector,
      fullName: String(record.fullName || "").trim(),
      marketCap: isETF ? null : marketCap,
      isETF: isETF,
      historyFile: historyFilename(ticker)
    };
  });

  function assertCanonicalModel(records) {
    if (records.length !== 50) {
      throw new Error("Expected exactly 50 canonical stock records; found " + records.length + ".");
    }
    const keys = records.map(function (record) { return record.tickerKey; });
    if (keys.some(function (key) { return !key; })) {
      throw new Error("Every stock record must have a non-empty ticker.");
    }
    if (new Set(keys).size !== records.length) {
      throw new Error("Ticker keys must be unique in the canonical stock model.");
    }
    records.forEach(function (record) {
      if (!record.fullName || !SECTOR_ORDER.includes(record.sector)) {
        throw new Error("Incomplete canonical record for " + record.ticker + ".");
      }
      if (!record.isETF && !Number.isFinite(record.marketCap)) {
        throw new Error("Non-ETF " + record.ticker + " is missing a valid market cap.");
      }
    });
  }

  assertCanonicalModel(stocks);

  const chart = d3.select("#stock-bubbles");
  const tooltip = d3.select("#tooltip");
  const nonETFMarketCaps = stocks.filter(function (record) { return !record.isETF; }).map(function (record) { return record.marketCap; });
  const radiusScale = d3.scaleSqrt()
    .domain(d3.extent(nonETFMarketCaps))
    .range([14, 50]);

  stocks.forEach(function (record, index) {
    const anchor = CLUSTER_ANCHORS[record.sector];
    const column = index % 5;
    const row = Math.floor(index / 5) % 3;
    record.radius = record.isETF ? 19 : radiusScale(record.marketCap);
    // Stable offsets avoid random initial positions before the fixed simulation ticks.
    record.x = anchor.x + (column - 2) * 22;
    record.y = anchor.y + (row - 1) * 24;
  });

  document.getElementById("record-count").textContent = String(stocks.length);
  document.getElementById("sector-count").textContent = String(new Set(stocks.map(function (record) { return record.sector; })).size);

  function formatMarketCap(value) {
    if (!Number.isFinite(value)) return "—";
    const units = [
      { limit: 1e12, suffix: "T" },
      { limit: 1e9, suffix: "B" },
      { limit: 1e6, suffix: "M" },
      { limit: 1e3, suffix: "K" }
    ];
    const unit = units.find(function (entry) { return value >= entry.limit; });
    if (!unit) return d3.format(",.0f")(value);
    const scaled = value / unit.limit;
    const decimals = scaled >= 100 ? 0 : scaled >= 10 ? 1 : 2;
    return scaled.toFixed(decimals).replace(/\.0+$|(?<=\.\d)0+$/, "") + unit.suffix;
  }

  function renderLegend() {
    const legend = d3.select("#sector-legend");
    legend.selectAll("span.legend-item")
      .data(SECTOR_ORDER.filter(function (sector) { return stocks.some(function (record) { return record.sector === sector; }); }))
      .join("span")
      .attr("class", "legend-item")
      .each(function (sector) {
        const item = d3.select(this);
        item.selectAll("span").remove();
        item.append("span")
          .attr("class", "legend-swatch")
          .style("background-color", SECTOR_COLORS[sector]);
        item.append("span").text(sector);
      });
  }

  renderLegend();

  const root = chart.append("g").attr("class", "chart-root");
  const haloLayer = root.append("g").attr("class", "cluster-halos");
  const clusterGroups = SECTOR_ORDER.map(function (sector) {
    return { sector: sector, anchor: CLUSTER_ANCHORS[sector], count: stocks.filter(function (record) { return record.sector === sector; }).length };
  });

  haloLayer.selectAll("circle.cluster-halo")
    .data(clusterGroups)
    .join("circle")
    .attr("class", "cluster-halo")
    .attr("cx", function (group) { return group.anchor.x; })
    .attr("cy", function (group) { return group.anchor.y; })
    .attr("r", function (group) { return group.sector === "ETF" ? 108 : 132; });

  haloLayer.selectAll("text.cluster-label")
    .data(clusterGroups)
    .join("text")
    .attr("class", "cluster-label")
    .attr("x", function (group) { return group.anchor.x; })
    .attr("y", function (group) { return group.anchor.y - (group.sector === "ETF" ? 91 : 116); })
    .text(function (group) { return group.sector; });

  function boundedForce() {
    let nodes;
    function force() {
      nodes.forEach(function (node) {
        node.x = Math.max(node.radius + 4, Math.min(WIDTH - node.radius - 4, node.x));
        node.y = Math.max(node.radius + 4, Math.min(HEIGHT - node.radius - 4, node.y));
      });
    }
    force.initialize = function (initializedNodes) { nodes = initializedNodes; };
    return force;
  }

  const simulation = d3.forceSimulation(stocks)
    .force("x", d3.forceX(function (record) { return CLUSTER_ANCHORS[record.sector].x; }).strength(0.14))
    .force("y", d3.forceY(function (record) { return CLUSTER_ANCHORS[record.sector].y; }).strength(0.14))
    .force("collide", d3.forceCollide(function (record) { return record.radius + 3; }).iterations(5).strength(1))
    .force("bounds", boundedForce())
    .stop();

  for (let tick = 0; tick < 520; tick += 1) simulation.tick();
  stocks.forEach(function (record) {
    record.x = Math.max(record.radius + 4, Math.min(WIDTH - record.radius - 4, record.x));
    record.y = Math.max(record.radius + 4, Math.min(HEIGHT - record.radius - 4, record.y));
  });

  const bubbleLayer = root.append("g").attr("class", "bubble-layer");
  const bubbles = bubbleLayer.selectAll("g.bubble")
    .data(stocks, function (record) { return record.tickerKey; })
    .join(function (enter) {
      const group = enter.append("g")
        .attr("class", function (record) { return "bubble" + (record.isETF ? " etf" : ""); })
        .attr("tabindex", 0)
        .attr("role", "button")
        .attr("aria-pressed", "false")
        .attr("aria-label", function (record) { return record.ticker + ": " + record.fullName; });
      group.append("circle")
        .attr("r", function (record) { return record.radius; })
        .style("fill", function (record) { return SECTOR_COLORS[record.sector]; });
      group.append("text")
        .attr("class", "bubble-label")
        .style("font-size", function (record) { return Math.max(9, Math.min(15, record.radius * 0.34)) + "px"; })
        .text(function (record) { return record.ticker; });
      return group;
    })
    .attr("data-ticker", function (record) { return record.tickerKey; })
    .attr("transform", function (record) { return "translate(" + record.x.toFixed(2) + "," + record.y.toFixed(2) + ")"; });

  const tableRows = d3.select("#stock-table tbody")
    .selectAll("tr.stock-row")
    .data(stocks, function (record) { return record.tickerKey; })
    .join("tr")
    .attr("class", "stock-row")
    .attr("data-ticker", function (record) { return record.tickerKey; })
    .attr("tabindex", 0)
    .attr("role", "button")
    .attr("aria-pressed", "false")
    .each(function (record) {
      const row = d3.select(this);
      row.append("td").attr("class", "ticker-cell").text(record.ticker);
      row.append("td").attr("class", "name-cell").attr("title", record.fullName).text(record.fullName);
      row.append("td").attr("class", "sector-cell").text(record.sector);
      row.append("td")
        .attr("class", "cap-cell numeric" + (record.isETF ? " etf-cap" : ""))
        .attr("aria-label", record.isETF ? "Market cap unavailable for ETF" : formatMarketCap(record.marketCap))
        .text(record.isETF ? "—" : formatMarketCap(record.marketCap));
    });

  let selectedTicker = null;

  function updateSelection() {
    bubbles
      .classed("selected", function (record) { return record.tickerKey === selectedTicker; })
      .attr("aria-pressed", function (record) { return String(record.tickerKey === selectedTicker); });
    tableRows
      .classed("selected", function (record) { return record.tickerKey === selectedTicker; })
      .attr("aria-pressed", function (record) { return String(record.tickerKey === selectedTicker); });
  }

  function selectTicker(tickerKey) {
    selectedTicker = tickerKey;
    updateSelection();
  }

  function hideTooltip() {
    tooltip.classed("visible", false).attr("aria-hidden", "true");
  }

  function showTooltip(event, record) {
    if (record.isETF) {
      hideTooltip();
      return;
    }
    tooltip.selectAll(".tooltip-ticker, .tooltip-name, .tooltip-sector").remove();
    tooltip.append("span").attr("class", "tooltip-ticker").text(record.ticker);
    tooltip.append("span").attr("class", "tooltip-name").text(record.fullName);
    tooltip.append("span").attr("class", "tooltip-sector").text(record.sector);
    tooltip.classed("visible", true).attr("aria-hidden", "false");
    const node = tooltip.node();
    const gap = 14;
    const maxX = window.innerWidth - node.offsetWidth - 10;
    const maxY = window.innerHeight - node.offsetHeight - 10;
    tooltip
      .style("left", Math.max(10, Math.min(event.clientX + gap, maxX)) + "px")
      .style("top", Math.max(10, Math.min(event.clientY + gap, maxY)) + "px");
  }

  bubbles
    .on("click", function (event, record) { selectTicker(record.tickerKey); })
    .on("keydown", function (event, record) {
      if (event.key === "Enter" || event.key === " ") {
        event.preventDefault();
        selectTicker(record.tickerKey);
      }
    })
    .on("mouseover", function (event, record) { showTooltip(event, record); })
    .on("mousemove", function (event, record) { if (!record.isETF) showTooltip(event, record); })
    .on("mouseout", hideTooltip);

  tableRows
    .on("click", function (event, record) { selectTicker(record.tickerKey); })
    .on("keydown", function (event, record) {
      if (event.key === "Enter" || event.key === " ") {
        event.preventDefault();
        selectTicker(record.tickerKey);
      }
    });

  updateSelection();
}());
"}

