        .attr("class", "bubble-label")
        .style("font-size", function (record) { return Math.max(9, Math.min(15, record.radius * 0.34)) + "px"; })
        .text(function (record) { return record.ticker; });
      return group;
    })
    .attr("data-ticker", function (record) { return record.tickerKey; })
    .attr("transform", function (record) { return "translate(" + record.x.toFixed(2) + "," + record.y.toFixed(2) + ")"; });

  const tableRows = d3.select("#stock-table tbody")
    .selectAll("tr.stock-row")
    .data(stocks, function (record) { return record.tickerKey; })
    .join("tr")
    .attr("class", "stock-row")
    .attr("data-ticker", function (record) { return record.tickerKey; })
    .attr("tabindex", 0)
    .attr("role", "button")
    .attr("aria-pressed", "false")
    .each(function (record) {
      const row = d3.select(this);
      row.append("td").attr("class", "ticker-cell").text(record.ticker);
      row.append("td").attr("class", "name-cell").attr("title", record.fullName).text(record.fullName);
      row.append("td").attr("class", "sector-cell").text(record.sector);
      row.append("td")
        .attr("class", "cap-cell numeric" + (record.isETF ? " etf-cap" : ""))
        .attr("aria-label", record.isETF ? "Market cap unavailable for ETF" : formatMarketCap(record.marketCap))
        .text(record.isETF ? "—" : formatMarketCap(record.marketCap));
