  function updateSelection() {
    bubbles
      .classed("selected", function (record) { return record.tickerKey === selectedTicker; })
      .attr("aria-pressed", function (record) { return String(record.tickerKey === selectedTicker); });
    tableRows
      .classed("selected", function (record) { return record.tickerKey === selectedTicker; })
      .attr("aria-pressed", function (record) { return String(record.tickerKey === selectedTicker); });
  }

  function selectTicker(tickerKey) {
    selectedTicker = tickerKey;
    updateSelection();
  }

