    return String(value || "").trim().toUpperCase();
  }

  function finitePositive(value) {
    const number = Number(value);
    return Number.isFinite(number) && number > 0 ? number : null;
  }

  function historyFilename(ticker) {
    const normalized = normalizeTicker(ticker);
    return normalized === "GLD" || normalized === "QQQ" || normalized === "SPY" ||
      normalized === "VEA" || normalized === "VOO" || normalized === "VTV" ||
      normalized === "VWO" || normalized === "XLF" || normalized === "XLU" ||
      normalized === "XLV" ? normalized.toLowerCase() + ".csv" : normalized + ".csv";
  }

  // Keep the source order stable: it groups the supplied records by sector.
  const stocks = SOURCE_RECORDS.map(function (record, index) {
    const ticker = normalizeTicker(record.ticker);
    const sector = String(record.sector || "").trim();
    const marketCap = finitePositive(record.marketCap);
    const isETF = sector === "ETF";
    return {
      sourceIndex: index,
      ticker: ticker,
      tickerKey: ticker,
      sector: sector,
      fullName: String(record.fullName || "").trim(),
      marketCap: isETF ? null : marketCap,
      isETF: isETF,
      historyFile: historyFilename(ticker)
    };
