    .force("x", d3.forceX(function (record) { return CLUSTER_ANCHORS[record.sector].x; }).strength(0.14))
    .force("y", d3.forceY(function (record) { return CLUSTER_ANCHORS[record.sector].y; }).strength(0.14))
    .force("collide", d3.forceCollide(function (record) { return record.radius + 3; }).iterations(5).strength(1))
    .force("bounds", boundedForce())
    .stop();

  for (let tick = 0; tick < 520; tick += 1) simulation.tick();
  stocks.forEach(function (record) {
    record.x = Math.max(record.radius + 4, Math.min(WIDTH - record.radius - 4, record.x));
    record.y = Math.max(record.radius + 4, Math.min(HEIGHT - record.radius - 4, record.y));
  });

  const bubbleLayer = root.append("g").attr("class", "bubble-layer");
  const bubbles = bubbleLayer.selectAll("g.bubble")
    .data(stocks, function (record) { return record.tickerKey; })
    .join(function (enter) {
      const group = enter.append("g")
        .attr("class", function (record) { return "bubble" + (record.isETF ? " etf" : ""); })
        .attr("tabindex", 0)
        .attr("role", "button")
        .attr("aria-pressed", "false")
        .attr("aria-label", function (record) { return record.ticker + ": " + record.fullName; });
      group.append("circle")
        .attr("r", function (record) { return record.radius; })
        .style("fill", function (record) { return SECTOR_COLORS[record.sector]; });
      group.append("text")
        .attr("class", "bubble-label")
        .style("font-size", function (record) { return Math.max(9, Math.min(15, record.radius * 0.34)) + "px"; })
        .text(function (record) { return record.ticker; });
      return group;
    })
    .attr("data-ticker", function (record) { return record.tickerKey; })
    .attr("transform", function (record) { return "translate(" + record.x.toFixed(2) + "," + record.y.toFixed(2) + ")"; });

  const tableRows = d3.select("#stock-table tbody")
    .selectAll("tr.stock-row")
    .data(stocks, function (record) { return record.tickerKey; })
    .join("tr")
    .attr("class", "stock-row")
    .attr("data-ticker", function (record) { return record.tickerKey; })
    .attr("tabindex", 0)
    .attr("role", "button")
    .attr("aria-pressed", "false")
    .each(function (record) {
      const row = d3.select(this);
      row.append("td").attr("class", "ticker-cell").text(record.ticker);
      row.append("td").attr("class", "name-cell").attr("title", record.fullName).text(record.fullName);
      row.append("td").attr("class", "sector-cell").text(record.sector);
      row.append("td")
        .attr("class", "cap-cell numeric" + (record.isETF ? " etf-cap" : ""))
        .attr("aria-label", record.isETF ? "Market cap unavailable for ETF" : formatMarketCap(record.marketCap))
        .text(record.isETF ? "—" : formatMarketCap(record.marketCap));
    });

  let selectedTicker = null;

  function updateSelection() {
    bubbles
      .classed("selected", function (record) { return record.tickerKey === selectedTicker; })
      .attr("aria-pressed", function (record) { return String(record.tickerKey === selectedTicker); });
    tableRows
      .classed("selected", function (record) { return record.tickerKey === selectedTicker; })
      .attr("aria-pressed", function (record) { return String(record.tickerKey === selectedTicker); });
  }

  function selectTicker(tickerKey) {
    selectedTicker = tickerKey;
    updateSelection();
  }

  function hideTooltip() {
    tooltip.classed("visible", false).attr("aria-hidden", "true");
  }

  function showTooltip(event, record) {
    if (record.isETF) {
      hideTooltip();
      return;
    }
    tooltip.selectAll(".tooltip-ticker, .tooltip-name, .tooltip-sector").remove();
    tooltip.append("span").attr("class", "tooltip-ticker").text(record.ticker);
    tooltip.append("span").attr("class", "tooltip-name").text(record.fullName);
    tooltip.append("span").attr("class", "tooltip-sector").text(record.sector);
    tooltip.classed("visible", true).attr("aria-hidden", "false");
    const node = tooltip.node();
    const gap = 14;
    const maxX = window.innerWidth - node.offsetWidth - 10;
    const maxY = window.innerHeight - node.offsetHeight - 10;
    tooltip
      .style("left", Math.max(10, Math.min(event.clientX + gap, maxX)) + "px")
      .style("top", Math.max(10, Math.min(event.clientY + gap, maxY)) + "px");
  }

  bubbles
    .on("click", function (event, record) { selectTicker(record.tickerKey); })
    .on("keydown", function (event, record) {
      if (event.key === "Enter" || event.key === " ") {
        event.preventDefault();
        selectTicker(record.tickerKey);
      }
    })
    .on("mouseover", function (event, record) { showTooltip(event, record); })
    .on("mousemove", function (event, record) { if (!record.isETF) showTooltip(event, record); })
    .on("mouseout", hideTooltip);

  tableRows
    .on("click", function (event, record) { selectTicker(record.tickerKey); })
    .on("keydown", function (event, record) {
      if (event.key === "Enter" || event.key === " ") {
        event.preventDefault();
        selectTicker(record.tickerKey);
      }
    });

  updateSelection();
}());
"}

