  for (let tick = 0; tick < 520; tick += 1) simulation.tick();
  stocks.forEach(function (record) {
    record.x = Math.max(record.radius + 4, Math.min(WIDTH - record.radius - 4, record.x));
    record.y = Math.max(record.radius + 4, Math.min(HEIGHT - record.radius - 4, record.y));
  });

  const bubbleLayer = root.append("g").attr("class", "bubble-layer");
  const bubbles = bubbleLayer.selectAll("g.bubble")
    .data(stocks, function (record) { return record.tickerKey; })
    .join(function (enter) {
      const group = enter.append("g")
        .attr("class", function (record) { return "bubble" + (record.isETF ? " etf" : ""); })
