    }
    tooltip.selectAll(".tooltip-ticker, .tooltip-name, .tooltip-sector").remove();
    tooltip.append("span").attr("class", "tooltip-ticker").text(record.ticker);
    tooltip.append("span").attr("class", "tooltip-name").text(record.fullName);
    tooltip.append("span").attr("class", "tooltip-sector").text(record.sector);
    tooltip.classed("visible", true).attr("aria-hidden", "false");
    const node = tooltip.node();
    const gap = 14;
    const maxX = window.innerWidth - node.offsetWidth - 10;
    const maxY = window.innerHeight - node.offsetHeight - 10;
    tooltip
      .style("left", Math.max(10, Math.min(event.clientX + gap, maxX)) + "px")
      .style("top", Math.max(10, Math.min(event.clientY + gap, maxY)) + "px");
  }

  bubbles
    .on("click", function (event, record) { selectTicker(record.tickerKey); })
    .on("keydown", function (event, record) {
      if (event.key === "Enter" || event.key === " ") {
        event.preventDefault();
        selectTicker(record.tickerKey);
      }
    })
    .on("mouseover", function (event, record) { showTooltip(event, record); })
    .on("mousemove", function (event, record) { if (!record.isETF) showTooltip(event, record); })
    .on("mouseout", hideTooltip);

  tableRows
    .on("click", function (event, record) { selectTicker(record.tickerKey); })
    .on("keydown", function (event, record) {
      if (event.key === "Enter" || event.key === " ") {
        event.preventDefault();
        selectTicker(record.tickerKey);
      }
    });

